select * from customer;

-- 1: Revenue Analysis
-- Compare total revenue generated by male and female customers

select gender , sum(purchase_amount) as revenue from customer
group by gender;


-- 2: Discount & spending Analysis
-- Identified discount users whose purchase amounts where at or above the overall average

select customer_id ,purchase_amount From customer
where discount_applied = 'Yes'
and purchase_amount >= (select avg(purchase_amount) from customer);


-- 3. Product Rating Analaysis
-- Ranked the top 5 products by average review rating

SELECT item_purchased , round(avg(review_rating),2) as "Average rating" from customer
group by item_purchased
order by avg(review_rating) desc
limit 5;

-- 4.shipping analysis
-- compared average purchased amounts for standard and express shipping

SELECT round(avg(purchase_amount),2) , shipping_type from customer
WHERE shipping_type in ("Express","Standard")
GROUP BY shipping_type;


-- 5.Subscription analysis-
-- Compared customer counts,average spending ,and total revenue between subscribers and non-subscribers

SELECT subscription_status , count(customer_id) AS total_customers, round(avg(purchase_amount),2) as avg_spend , round(sum(purchase_amount),2) as total_revenue FROM customer
group by subscription_status
order by total_revenue desc,avg_spend desc;


-- 6. Descount dependency Analysis
-- Identified the top 5  products by percentage of purchases  with discount applied

select item_purchased, round( 100 * sum(case when discount_applied = 'Yes' then 1 else 0 end)/count(*),2) as discount_rate from customer
group by item_purchased
order by discount_rate desc
limit 5;


-- 7.Customer segmentation -
-- classified customers into New , Reurning , and loyal segements based  on previous purchases.

-- WITH is used to create something called a CTE (Common Table Expression).
-- Think of a CTE as a temporary named result that you can use in your main SQL query.

with customer_type as
	( select customer_id , previous_purchases,
		case when previous_purchases = 1 then 'New'
        when previous_purchases between 2 and 10 then 'Returning'
        else 'Loyal'
        end as customer_segment
        from customer
    )
select customer_segment , count(*) as Number_of_Customers from customer_type
group by customer_segment
-- SELECT * FROM customer_type;

-- 8.Product popularity Analysis 
-- Identified the top 3 most purchased products witin each category

-- ROW_NUMBER() is a SQL window function that assigns a sequential number to each row.
-- OVER() specifies how the window function should calculate its result.
-- PARTITION BY divides your data into separate groups based on a column.
-- What is ORDER BY COUNT(customer_id) DESC? This tells SQL how to arrange the rows before assigning row numbers.

with item_counts as 
	(select category, item_purchased, count(customer_id) as total_orders, row_number() over (partition by category order by count(customer_id) desc) as item_rank
    from customer
    group by category , item_purchased)
    
select item_rank , category , item_purchased , total_orders from item_counts
where item_rank <= 3;



-- 9.Repeat buyer analysis
-- compared subscription status among customers with more than 5 previous purchase

select subscription_status,  count(customer_id) as repeated_buyers from customer
where previous_purchases > 5
group by subscription_status;



-- 10. age group revenue analysis
-- compared total revenue across customer age groups.

select sum(purchase_amount) as total_revenue , age_group from customer
group by age_group
order by total_revenue desc;